// Chip naming the warbond a weapon or stratagem unlocks from (dist/data/warbond-sources.js,
// generated by scripts/build-warbonds.mjs), linking to that item on the warbond board.
// Weapons sold in the Superstore (dist/data/superstore.js) get a Superstore chip instead.
import { warbondSources } from '../data/warbond-sources.js';
import { superstorePages } from '../data/superstore.js';
import { formatRoute } from '../core/route.js';
import { html, icon } from './dom.js';
import { L } from '../core/i18n.js';

const superstoreItems = new Map(superstorePages.flatMap(page => page.items
  .filter(item => item.ref && item.ref.view !== 'armor')
  .map(item => [`${item.ref.view}/${item.ref.id}`, { page: page.number, cost: item.cost }])));
// Not on any warbond or store page: the wiki's MP-98 Knight Procurement section ("included in the Super Citizen Edition").
const EDITION = { 'gear/knight': { name: '슈퍼 시민 에디션', en: 'Super Citizen Edition' } };

export function warbondChip(view, id) {
  const key = `${view}/${id}`;
  const store = superstoreItems.get(key);
  if (store) return html`<a class="badge warbond" href="${formatRoute({ view: 'superstore' })}" title="${L(`슈퍼 스토어 ${store.page}페이지 · ${store.cost} 슈퍼 크레딧`, `Superstore page ${store.page} · ${store.cost} Super Credits`)}">${icon('warbonds', 14)}${L('슈퍼 스토어', 'Superstore')}</a>`;
  const edition = EDITION[key];
  if (edition) return html`<span class="badge warbond" title="${L('슈퍼 시민 에디션 구매 시 지급', 'Included with the Super Citizen Edition')}">${icon('warbonds', 14)}${L(edition.name, edition.en)}</span>`;
  const source = warbondSources[key];
  if (!source) return '';
  const free = source.price === 0;
  const href = formatRoute({ view: 'warbonds', id: source.id, query: { item: key } });
  const title = free
    ? L(`무료 전쟁 채권 ${source.page}페이지에서 해금`, `Unlocked on page ${source.page} of this free warbond`)
    : L(`전쟁 채권을 구매한 뒤 ${source.page}페이지에서 해금`, `Unlocked on page ${source.page} after buying this warbond`);
  return html`<a class="badge warbond" href="${href}" title="${title}">${icon('warbonds', 14)}${L(source.name, source.en)}${free ? L(' · 무료', ' · free') : ''}</a>`;
}
